DROP TABLE IF EXISTS `dp_dataset_version`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dp_dataset_version` (
  `version_id` bigint NOT NULL AUTO_INCREMENT COMMENT '版本ID',
  `dataset_id` bigint NOT NULL COMMENT '数据集ID',
  `version_no` int NOT NULL COMMENT '版本号',
  `version_name` varchar(100) DEFAULT '' COMMENT '版本名称',
  `definition_json` longtext NOT NULL COMMENT '结构化定义JSON',
  `schema_version` int DEFAULT '1' COMMENT '定义结构版本',
  `revision` int DEFAULT '0' COMMENT '乐观锁版本',
  `version_status` varchar(16) DEFAULT 'DRAFT' COMMENT 'DRAFT ONLINE OFFLINE',
  `health_status` varchar(16) DEFAULT 'INVALID' COMMENT 'VALID INVALID',
  `validation_message` varchar(2000) DEFAULT '' COMMENT '校验信息',
  `release_note` varchar(500) DEFAULT '' COMMENT '发布说明',
  `publish_by` varchar(64) DEFAULT '',
  `publish_time` datetime DEFAULT NULL,
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`version_id`),
  UNIQUE KEY `uk_dp_dataset_version` (`dataset_id`,`version_no`),
  KEY `idx_dp_dataset_version_status` (`dataset_id`,`version_status`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='数据集版本表';
/*!40101 SET character_set_client = @saved_cs_client */;

