  `audit_comment` varchar(500) DEFAULT '' COMMENT '审批意见',
  `request_id` varchar(64) DEFAULT NULL COMMENT '关联请求ID（如元数据变更ID）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `detail_json` text COMMENT '变更明细快照（JSON）',
  PRIMARY KEY (`log_id`),
  KEY `idx_tl_audit_biz` (`biz_type`,`biz_id`)
) ENGINE=InnoDB AUTO_INCREMENT=290 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='标签审批日志表';
