--
-- Table structure for table `tl_tag`
--

DROP TABLE IF EXISTS `tl_tag`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tl_tag` (
  `tag_id` bigint NOT NULL AUTO_INCREMENT COMMENT '标签ID',
  `library_id` bigint NOT NULL COMMENT '所属标签库ID',
  `dir_id` bigint NOT NULL COMMENT '所属目录ID',
  `field_name` varchar(64) NOT NULL COMMENT '源字段名',
  `tag_name` varchar(128) NOT NULL COMMENT '标签中文名',
  `data_type` varchar(32) DEFAULT '' COMMENT '源字段数据类型',
  `tag_type` varchar(16) DEFAULT '' COMMENT '标签类型（字典 tag_type）',
  `is_object_key` char(1) DEFAULT '0' COMMENT '是否对象键（0否 1是）',
  `business_caliber` varchar(500) DEFAULT '' COMMENT '业务口径',
  `tech_caliber` varchar(500) DEFAULT '' COMMENT '技术口径',
  `valid_period` varchar(32) DEFAULT '永久有效' COMMENT '有效日期',
  `update_cycle` varchar(8) DEFAULT '日' COMMENT '更新周期（字典 tag_update_cycle）',
  `create_way` varchar(8) DEFAULT '同步' COMMENT '创建方式（同步/自建）',
  `status` char(1) DEFAULT '0' COMMENT '状态（0草稿 1待审批 2已上线 3已下线 4待完善）',
  `version` int DEFAULT '1' COMMENT '版本号',
  `source_version_id` bigint DEFAULT NULL COMMENT '来源数据集版本ID（最近一次同步解析的版本）',
  `source_snapshot` varchar(1000) DEFAULT NULL COMMENT '来源字段快照JSON（数据源/物理表/物理列/数据类型/主键标记）',
  `source_fingerprint` varchar(64) DEFAULT NULL COMMENT '来源指纹（最近同步观察值）',
  `confirmed_fingerprint` varchar(64) DEFAULT NULL COMMENT '已确认来源指纹（元数据审核通过时写入）',
  `source_status` varchar(16) NOT NULL DEFAULT 'AVAILABLE' COMMENT '来源状态（AVAILABLE当前版本可用 MISSING来源缺失 CHANGED来源变更待确认）',
  `del_flag` varchar(64) DEFAULT '0' COMMENT '删除标志（0存在 其他=删除时的记录ID）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`tag_id`),
  UNIQUE KEY `uk_tl_tag_field` (`library_id`,`field_name`,`del_flag`),
  KEY `idx_tl_tag_library_status` (`library_id`,`status`),
  KEY `idx_tl_tag_dir` (`dir_id`)
) ENGINE=InnoDB AUTO_INCREMENT=525 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='标签表（字段快照）';
