DROP TABLE IF EXISTS `tl_tag_code_value`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tl_tag_code_value` (
  `value_id` bigint NOT NULL AUTO_INCREMENT COMMENT '码值ID',
  `library_id` bigint NOT NULL COMMENT '所属标签库ID',
  `field_name` varchar(64) NOT NULL COMMENT '标签名称（英文，源字段名）',
  `tag_name` varchar(128) DEFAULT '' COMMENT '标签名称（中文）',
  `code` varchar(500) NOT NULL COMMENT '标签码值（宽表存储值）',
  `code_definition` varchar(500) DEFAULT '' COMMENT '码值定义（显示值，选项展示用）',
  `order_num` int DEFAULT '0' COMMENT '码值排序',
  `source` varchar(16) DEFAULT 'MANUAL' COMMENT '码值来源（SYNC=宽表同步 MANUAL=手工录入）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '最近一次更新日期',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`value_id`),
  UNIQUE KEY `uk_tl_cv_field_code` (`library_id`,`field_name`,`code`)
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='标签码值表';
